import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        Q = int(next(iterator))
    except StopIteration:
        return

    parent = {}
    weight = {}

    parent[1] = 0
    weight[1] = 0

    cnt = 1
    last = 0

    for _ in range(Q):
        try:
            t_str = next(iterator)
            p_str = next(iterator)
            q_str = next(iterator)

            t = int(t_str)
            p = int(p_str)
            q = int(q_str)

            if t == 1:
                R = p ^ last
                W = q ^ last

                cnt += 1
                parent[cnt] = R
                weight[cnt] = W
            else:
                R = p ^ last
                X = q ^ last

                curr = R
                current_sum = 0
                length = 0

                while curr != 0:
                    w = weight[curr]

                    if current_sum + w > X:
                        break

                    current_sum += w
                    length += 1

                    par = parent[curr]
                    if par == 0:
                        break

                    if weight[par] >= w:
                        curr = par
                    else:
                        break

                last = length
                print(last)

        except StopIteration:
            break

if __name__ == "__main__":
    main()
